import {downloadFile} from './experience.js';
export function initBillingCheckout({billing,dialog,plans,getState,onApproved}){
 const controls=document.createElement('section');controls.className='billing-checkout';controls.hidden=true;controls.innerHTML='<p class="billing-environment"></p><label>E-mail para o pagamento <span>(opcional)</span><input class="checkout-email" type="email" autocomplete="email" maxlength="254" placeholder="seuemail@exemplo.com"></label><button type="button" class="button primary checkout-go">Continuar no Mercado Pago</button><button type="button" class="button outline checkout-check" hidden>Já paguei · verificar confirmação</button><button type="button" class="checkout-save-access" hidden>Guardar acesso da minha compra</button><p class="checkout-status" role="status"></p><small>O pagamento é confirmado pelo servidor. Após a confirmação, você personaliza e publica o presente. Guarde o acesso da compra para voltar em outro aparelho.</small>';dialog.append(controls);
 let selected=plans[1],record=null,busy=false,poll=null,notified='';const status=controls.querySelector('.checkout-status'),go=controls.querySelector('.checkout-go'),check=controls.querySelector('.checkout-check'),backup=controls.querySelector('.checkout-save-access');
 function stop(){clearTimeout(poll);poll=null;}dialog.addEventListener('close',stop);
 function inform(){if(!record)return;check.hidden=record.status!=='pending';backup.hidden=!record.id;go.hidden=record.status==='approved';if(record.status==='approved'){status.textContent='Pagamento confirmado! Seu mimo já pode ser criado e publicado.';if(notified!==record.id&&record.draftId===getState().draftId){notified=record.id;stop();dialog.close();if(new URLSearchParams(location.search).has('compra'))history.replaceState(null,'',location.pathname+location.hash);const plan=plans.find(p=>p.id===record.planId)||selected,hasDraft=!!(getState().recipient||getState().planId||getState().pages?.length);const preferred=hasDraft?getState().format:getState().checkoutFormat||record.requestedFormat||plan.format,format=billing.config.plans?.[plan.id]?.formats.includes(preferred)?preferred:plan.format;onApproved({...plan,format},record);}}else if(record.status==='failed'){status.textContent='O pagamento não foi aprovado. Você pode tentar novamente no Mercado Pago.';go.textContent='Tentar outro pagamento';}else if(record.status==='revoked'){status.textContent='Este pagamento foi cancelado ou reembolsado. Entre em contato com quem vendeu o presente se precisar de ajuda.';}else status.textContent='Aguardando a confirmação do Mercado Pago. Se pagou com Pix, aguarde alguns instantes.';}
 async function refresh(sync=false){if(!record?.id||busy)return;busy=true;check.disabled=true;try{record=await billing.refresh(record,sync);inform();}catch(e){status.textContent=e.message;}finally{busy=false;check.disabled=false;}if(dialog.open&&record?.status==='pending'){stop();poll=setTimeout(()=>refresh(),5000);}}
 function render(){const config=billing.config;controls.hidden=!config.checkoutReady;dialog.querySelector('.order-test').hidden=!!config.checkoutReady;dialog.querySelector('.order-demo-label').textContent=config.checkoutReady?(config.mode==='test'?'Ambiente de teste · nenhum valor real será cobrado':'Pagamento seguro · Mercado Pago'):'Demonstração · nenhum pagamento será feito';dialog.querySelector('.order-flow').nextElementSibling.hidden=!!config.checkoutReady;controls.querySelector('.billing-environment').textContent=config.mode==='test'?'Você está testando o fluxo. Use somente os dados de teste do Mercado Pago.':'Pix e cartão disponíveis no checkout do Mercado Pago.';if(!controls.hidden){const candidates=[billing.find()].filter(Boolean);record=candidates.find(r=>r.planId===selected.id)||null;go.hidden=false;go.textContent=config.mode==='test'?'Abrir checkout de teste':'Continuar no Mercado Pago';check.hidden=!record?.id;backup.hidden=!record?.id;status.textContent='';inform();}}
 async function show(plan){selected=plan;stop();await billing.ready;render();if(record?.id&&dialog.open)await refresh();}
 go.addEventListener('click',async()=>{if(busy)return;const email=controls.querySelector('.checkout-email');if(!email.reportValidity())return;busy=true;go.disabled=true;status.textContent='Preparando seu pagamento…';try{record=await billing.checkout(selected.id,email.value.trim());inform();if(record.checkoutUrl){status.textContent='Abrindo o pagamento seguro…';location.assign(record.checkoutUrl);}else if(record.status==='preparing'){status.textContent='Preparando o checkout. Aguarde alguns segundos e tente novamente.';}}catch(e){status.textContent=e.message;}finally{busy=false;go.disabled=false;}});
 check.addEventListener('click',()=>refresh(true));backup.addEventListener('click',()=>downloadFile('capimimo-acesso-da-compra.json',billing.backup()));
 billing.ready.then(()=>{render();const id=new URLSearchParams(location.search).get('compra'),returning=billing.get(id);if(returning){record=returning;selected=plans.find(p=>p.id===record.planId)||selected;document.dispatchEvent(new CustomEvent('billing:resume',{detail:record}));}});
 document.addEventListener('billing:change',()=>{if(dialog.open&&record?.id){const fresh=billing.get(record.id);if(fresh)record=fresh;inform();}});
 return{show,resume(order){record=order;selected=plans.find(p=>p.id===order.planId)||selected;render();record=order;inform();refresh(true);}};
}
